/**
 * outreachUnsubscribe.js — HMAC-verified one-click unsubscribe for cold-email
 * (employer outreach) campaigns.
 *
 * Mirrors jobAlertUnsubscribe.js (RFC 8058):
 * 1. Verifies HMAC token (companyKey signed with NEWSLETTER_SECRET).
 * 2. Writes employer_outreach_suppression/{companyKey} so send-cold-emails.mjs
 *    skips the company on the next touch.
 * 3. Returns a minimal IT HTML confirmation page (GET) or 200 OK (POST, RFC 8058).
 *
 * URLs are generated by scripts/lib/outreach-unsubscribe-token.mjs
 * (makeUnsubToken / buildUnsubUrl) — the HMAC scheme MUST stay byte-identical:
 *   token = HMAC-SHA256(secret, `outreach_unsub:${companyKey}`) hex digest.
 *
 * RFC 8058 compliance:
 * - List-Unsubscribe: <https://.../disiscrivi-outreach/?c=X&t=Z>, <mailto:...>
 * - List-Unsubscribe-Post: List-Unsubscribe=One-Click
 * - POST body "List-Unsubscribe=One-Click" triggers unsubscribe; companyKey +
 *   token travel in the URI query string (mirrors jobAlertUnsubscribe).
 */

import { createHmac, timingSafeEqual } from 'node:crypto';
import admin from 'firebase-admin';
import { getAdminDb } from './newsletterResendWebhookCore.js';

const BASE_URL = 'https://frontaliereticino.ch';
const BRAND_ORANGE = '#f97316';
const BRAND_DARK = '#0f172a';
const LIGHT_BG = '#f1f5f9';
const CARD_BG = '#ffffff';
const MUTED_COLOR = '#64748b';
const BORDER_COLOR = '#e2e8f0';

const SUPPRESSION_COLLECTION = 'employer_outreach_suppression';

/**
 * Generate HMAC token for outreach unsubscribe.
 * Distinct prefix avoids collision with job-alert / newsletter tokens that
 * share NEWSLETTER_SECRET. MUST match scripts/lib/outreach-unsubscribe-token.mjs.
 */
export function generateOutreachUnsubToken(companyKey, secret) {
  return createHmac('sha256', secret)
    .update(`outreach_unsub:${String(companyKey).trim()}`)
    .digest('hex');
}

export function verifyOutreachToken(companyKey, token, secret) {
  if (!secret || !companyKey || !token) return false;
  const expected = generateOutreachUnsubToken(companyKey, secret);
  try {
    return timingSafeEqual(Buffer.from(token, 'hex'), Buffer.from(expected, 'hex'));
  } catch {
    return false;
  }
}

function buildConfirmationHtml({ title, message, success }) {
  const icon = success ? '✅' : '⚠️';
  return `<!DOCTYPE html>
<html lang="it">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title} – Frontaliere Ticino</title>
  <style>body { margin:0; padding:0; background:${LIGHT_BG}; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; }</style>
</head>
<body>
  <table width="100%" cellpadding="0" cellspacing="0" style="background:${LIGHT_BG};padding:48px 16px;">
    <tr><td align="center">
      <table width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;">
        <tr><td style="text-align:center;padding-bottom:24px;">
          <a href="${BASE_URL}" style="text-decoration:none;">
            <div style="font-size:22px;font-weight:800;color:${BRAND_ORANGE};">
              <span style="color:${BRAND_ORANGE};">●</span> Frontaliere Ticino
            </div>
            <div style="font-size:12px;color:${MUTED_COLOR};letter-spacing:.04em;">La guida del frontaliere</div>
          </a>
        </td></tr>
        <tr><td style="background:${CARD_BG};border:1px solid ${BORDER_COLOR};border-radius:16px;padding:32px 28px;text-align:center;">
          <div style="font-size:36px;margin-bottom:12px;">${icon}</div>
          <div style="font-size:24px;font-weight:800;color:${BRAND_DARK};padding-bottom:12px;">${title}</div>
          <div style="font-size:15px;line-height:1.6;color:#334155;">${message}</div>
        </td></tr>
        <tr><td style="text-align:center;padding:20px 0;">
          <a href="${BASE_URL}/" style="font-size:14px;color:${BRAND_ORANGE};text-decoration:none;font-weight:600;">Vai a Frontaliere Ticino →</a>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;
}

/**
 * Core handler. `db` is injectable for unit tests.
 * Always idempotent: a repeat unsubscribe re-writes the suppression doc with a
 * fresh serverTimestamp and returns 200.
 */
export async function handleOutreachUnsubscribe({ companyKey, token, secret, db: injectedDb }) {
  const key = String(companyKey || '').trim();

  if (!key) {
    return {
      status: 400,
      html: buildConfirmationHtml({
        title: 'Parametri mancanti',
        message: 'Il link di disiscrizione non è valido. Prova a cliccare di nuovo dall\'email.',
        success: false,
      }),
    };
  }

  if (!verifyOutreachToken(key, token, secret)) {
    return {
      status: 403,
      html: buildConfirmationHtml({
        title: 'Link non valido',
        message: 'Il link di disiscrizione è scaduto o non valido. Puoi rispondere "STOP" all\'email per essere rimosso.',
        success: false,
      }),
    };
  }

  const db = injectedDb || getAdminDb();
  await db.collection(SUPPRESSION_COLLECTION).doc(key).set({
    companyKey: key,
    suppressedAt: admin.firestore.FieldValue.serverTimestamp(),
    source: 'one-click',
  }, { merge: true });

  return {
    status: 200,
    html: buildConfirmationHtml({
      title: 'Sei stato rimosso',
      message: 'Non riceverai più email da Frontaliere Ticino per questa azienda. Se cambi idea, puoi sempre scriverci.',
      success: true,
    }),
  };
}
